head.b:skin:
/* ==========================================================
   MoneyEnlight Blogger Theme
   Dark finance theme: #050b10 bg, emerald brand, glass cards
   ========================================================== */

:root {
  --bg: #050b10;
  --bg-card: rgba(255, 255, 255, 0.04);
  --bg-card-hover: rgba(255, 255, 255, 0.07);
  --border: rgba(255, 255, 255, 0.08);
  --border-strong: rgba(255, 255, 255, 0.15);
  --text: #e6f4ef;
  --text-soft: rgba(255, 255, 255, 0.65);
  --text-faint: rgba(255, 255, 255, 0.45);
  --brand-50: #ecfdf5;
  --brand-400: #34d399;
  --brand-500: #10b981;
  --brand-600: #059669;
  --brand-700: #047857;
  --red: #dc2626;
  --red-hover: #ef4444;
  --radius: 10px;
  color-scheme: dark;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  background-image:
    radial-gradient(circle at 25% 0%, rgba(16,185,129,0.12), transparent 40%),
    radial-gradient(circle at 80% 0%, rgba(99,102,241,0.10), transparent 40%);
  background-repeat: no-repeat;
}

a { color: var(--brand-400); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--brand-50); }

img { max-width: 100%; height: auto; }

.container {
  max-width: 1120px;
  margin: 0 auto;
  padding: 0 16px;
}

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  background: rgba(5, 11, 16, 0.72);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.header-inner {
  max-width: 1120px;
  margin: 0 auto;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.site-title a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text);
}
.site-title a:hover { color: var(--text); }
.site-title .brand-accent { color: var(--brand-400); }
.site-logo-svg { height: 22px; width: 22px; flex-shrink: 0; }
.site-tagline {
  display: none;
  font-size: 12px;
  color: var(--text-faint);
  font-weight: 400;
  margin-left: 4px;
}
@media (min-width: 900px) { .site-tagline { display: inline; } }

.header-right-col {
  display: flex;
  align-items: center;
  gap: 20px;
}

.header-nav ul {
  display: flex;
  align-items: center;
  gap: 22px;
  list-style: none;
}
.header-nav a {
  font-size: 14px;
  color: rgba(255,255,255,0.7);
  font-weight: 500;
}
.header-nav a:hover { color: #fff; }

.header-actions { display: flex; align-items: center; gap: 12px; }

.yt-subscribe-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--red);
  color: #fff !important;
  font-size: 12.5px;
  font-weight: 600;
  padding: 7px 14px;
  border-radius: 999px;
  white-space: nowrap;
  transition: background 0.2s;
}
.yt-subscribe-btn:hover { background: var(--red-hover); color: #fff; }
.yt-subscribe-btn svg { height: 15px; width: 15px; }

.search-icon {
  display: inline-flex;
  align-items: center;
  color: rgba(255,255,255,0.6);
  padding: 6px;
}
.search-icon:hover { color: #fff; }

/* Mobile menu */
.mobile-menu-toggle {
  display: none;
  cursor: pointer;
  color: var(--text);
  padding: 4px;
}
.mobile-close-btn { display: none; cursor: pointer; color: var(--text); }
.mobile-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  z-index: 90;
}
.mobile-overlay.active { display: block; }

@media (max-width: 768px) {
  .mobile-menu-toggle { display: block; }
  .header-right-col {
    position: fixed;
    top: 0;
    right: -290px;
    width: 280px;
    height: 100vh;
    background: #0a1118;
    border-left: 1px solid var(--border);
    flex-direction: column;
    align-items: flex-start;
    padding: 60px 24px 24px;
    gap: 24px;
    z-index: 100;
    transition: right 0.3s ease;
    overflow-y: auto;
  }
  .header-right-col.open { right: 0; }
  .mobile-close-btn {
    display: block;
    position: absolute;
    top: 16px;
    right: 16px;
  }
  .header-nav ul { flex-direction: column; align-items: flex-start; gap: 18px; }
  .header-nav a { font-size: 16px; }
}

/* ---------- Hero (homepage) ---------- */
.hero-section {
  border-bottom: 1px solid rgba(255,255,255,0.05);
  padding: 64px 0 56px;
}
.hero-kicker {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--text-faint);
}
.hero-title {
  margin-top: 16px;
  max-width: 760px;
  font-size: clamp(28px, 5vw, 44px);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.hero-title .gradient-text {
  background: linear-gradient(90deg, #34d399, #60a5fa, #a78bfa);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero-sub {
  margin-top: 16px;
  max-width: 620px;
  color: var(--text-soft);
  font-size: 16.5px;
}
.hero-actions {
  margin-top: 30px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--brand-600);
  color: #fff !important;
  font-size: 14px;
  font-weight: 600;
  padding: 11px 18px;
  border-radius: 8px;
  transition: background 0.2s;
}
.btn-primary:hover { background: var(--brand-500); }
.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,0.05);
  border: 1px solid var(--border-strong);
  color: #fff !important;
  font-size: 14px;
  font-weight: 600;
  padding: 11px 18px;
  border-radius: 8px;
  transition: background 0.2s;
}
.btn-ghost:hover { background: rgba(255,255,255,0.1); }

/* ---------- Layout ---------- */
.layout-wrapper {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 40px;
  padding-top: 40px;
  padding-bottom: 40px;
}
@media (max-width: 980px) {
  .layout-wrapper { grid-template-columns: 1fr; }
}

.blog-section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 24px;
}
.blog-section-header h2 {
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.blog-section-header a { font-size: 14px; color: var(--brand-400); }

/* ---------- Post cards (list view) ---------- */
.post-list { display: flex; flex-direction: column; gap: 20px; }

.post {
  display: flex;
  gap: 0;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: background 0.2s, border-color 0.2s, transform 0.2s;
}
.post:hover {
  background: var(--bg-card-hover);
  border-color: rgba(52, 211, 153, 0.35);
  transform: translateY(-2px);
}

.post-thumbnail {
  width: 240px;
  flex-shrink: 0;
  background: rgba(255,255,255,0.03);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-faint);
  overflow: hidden;
}
.post-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.post-content { padding: 20px 24px; min-width: 0; }

.post-title {
  font-size: 19px;
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -0.01em;
  margin-bottom: 8px;
}
.post-title a { color: var(--text); }
.post-title a:hover { color: var(--brand-400); }

.post-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-faint);
  margin-bottom: 10px;
}

.post-body { color: var(--text-soft); font-size: 15px; }
.post-body p { margin-bottom: 12px; }

.read-more-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--brand-400);
}
.read-more-btn:hover { color: var(--brand-50); }

@media (max-width: 640px) {
  .post { flex-direction: column; }
  .post-thumbnail { width: 100%; height: 180px; }
  .post-content { padding: 16px; }
}

/* ---------- Single post ---------- */
.post-full {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 36px 40px;
}
@media (max-width: 640px) {
  .post-full { padding: 20px 16px; background: transparent; border: none; }
}

.post-full-title {
  font-size: clamp(26px, 4vw, 36px);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.post-full-content { margin-top: 24px; color: var(--text-soft); }
.post-full-content h2, .post-full-content h3, .post-full-content h4 {
  color: var(--text);
  margin: 28px 0 12px;
  letter-spacing: -0.01em;
  line-height: 1.3;
}
.post-full-content h2 { font-size: 24px; }
.post-full-content h3 { font-size: 20px; }
.post-full-content p { margin-bottom: 16px; }
.post-full-content ul, .post-full-content ol { margin: 0 0 16px 22px; }
.post-full-content li { margin-bottom: 6px; }
.post-full-content img { border-radius: 8px; margin: 8px 0; }
.post-full-content blockquote {
  border-left: 3px solid var(--brand-500);
  background: rgba(16,185,129,0.06);
  padding: 12px 18px;
  margin: 16px 0;
  border-radius: 0 8px 8px 0;
  color: var(--text);
}
.post-full-content table {
  width: 100%;
  border-collapse: collapse;
  margin: 16px 0;
  font-size: 14.5px;
  display: block;
  overflow-x: auto;
}
.post-full-content th, .post-full-content td {
  border: 1px solid var(--border);
  padding: 10px 14px;
  text-align: left;
}
.post-full-content th {
  background: rgba(255,255,255,0.05);
  color: var(--text);
  font-weight: 600;
}
.post-full-content code {
  background: rgba(255,255,255,0.08);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 2px 6px;
  font-size: 0.9em;
  color: var(--brand-400);
}
.post-full-content pre {
  background: #0a1118;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px 18px;
  overflow-x: auto;
  margin: 16px 0;
}
.post-full-content pre code {
  background: none;
  border: none;
  padding: 0;
  color: var(--text);
}

.post-labels { margin-top: 28px; display: flex; flex-wrap: wrap; gap: 8px; }
.post-labels a {
  display: inline-block;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--brand-400);
  background: rgba(16,185,129,0.08);
  border: 1px solid rgba(16,185,129,0.25);
  border-radius: 999px;
  padding: 4px 12px;
}
.post-labels a:hover { background: rgba(16,185,129,0.15); }

/* ---------- Pagination ---------- */
.blog-pager {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 32px;
}
.blog-pager a {
  display: inline-flex;
  align-items: center;
  background: rgba(255,255,255,0.05);
  border: 1px solid var(--border-strong);
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  padding: 9px 16px;
  border-radius: 8px;
  transition: background 0.2s;
}
.blog-pager a:hover { background: rgba(255,255,255,0.1); }
.blog-pager-older-link { margin-left: auto; }

/* ---------- Sidebar widgets ---------- */
.sidebar-area { min-width: 0; }
.sidebar .widget {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  margin-bottom: 20px;
}
.widget-title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--text-faint);
  margin-bottom: 14px;
}

.popular-posts-list { list-style: none; }
.popular-posts-list li {
  padding: 9px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.popular-posts-list li:last-child { border-bottom: none; }
.popular-posts-list a {
  color: var(--text-soft);
  font-size: 14.5px;
  font-weight: 500;
  line-height: 1.4;
}
.popular-posts-list a:hover { color: var(--brand-400); }

.list-label-widget-content ul { list-style: none; }
.list-label-widget-content li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.list-label-widget-content li:last-child { border-bottom: none; }
.list-label-widget-content a { color: var(--text-soft); font-size: 14.5px; }
.list-label-widget-content a:hover { color: var(--brand-400); }
.list-label-widget-content span {
  font-size: 12px;
  color: var(--brand-400);
  background: rgba(16,185,129,0.1);
  border-radius: 999px;
  padding: 1px 9px;
}

/* Newsletter form */
.newsletter-text { margin-bottom: 14px; color: var(--text-soft); font-size: 14.5px; }
.newsletter-input {
  width: 100%;
  padding: 11px 14px;
  background: rgba(255,255,255,0.05);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 14.5px;
  font-family: inherit;
}
.newsletter-input:focus {
  outline: none;
  border-color: var(--brand-500);
}
.newsletter-input::placeholder { color: var(--text-faint); }
.newsletter-btn {
  width: 100%;
  background: var(--brand-600);
  color: #fff;
  border: none;
  padding: 11px 14px;
  border-radius: 8px;
  font-size: 14.5px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.2s;
}
.newsletter-btn:hover { background: var(--brand-500); }
.newsletter-btn:disabled { opacity: 0.6; cursor: default; }

/* ---------- Error page ---------- */
.error-page {
  text-align: center;
  padding: 100px 16px;
}
.error-page h1 {
  font-size: 72px;
  font-weight: 700;
  background: linear-gradient(90deg, #34d399, #60a5fa, #a78bfa);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.error-page p { color: var(--text-soft); margin: 12px 0 24px; }

/* ---------- Footer ---------- */
.site-footer {
  margin-top: 80px;
  border-top: 1px solid rgba(255,255,255,0.05);
  padding: 40px 0 32px;
  font-size: 14px;
  color: var(--text-faint);
}
.footer-top {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  text-align: center;
}
@media (min-width: 640px) {
  .footer-top {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
  }
}
.footer-social { display: flex; align-items: center; gap: 18px; }
.footer-social a {
  color: rgba(255,255,255,0.55);
  display: inline-flex;
  align-items: center;
}
.footer-social a:hover { color: var(--brand-400); }
.footer-social svg { height: 20px; width: 20px; }

.footer-links {
  margin-top: 18px;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 18px;
  font-size: 12.5px;
}
@media (min-width: 640px) { .footer-links { justify-content: flex-start; } }
.footer-links a { color: var(--text-faint); }
.footer-links a:hover { color: #fff; }

/* Hide Blogger default clutter */
.widget-item-control, .quickedit { display: none !important; }

/* Entrance animation */
@keyframes fadeSlideUp {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}
.hero-section .container > * { animation: fadeSlideUp 0.7s ease-out both; }
.hero-section .container > *:nth-child(2) { animation-delay: 0.1s; }
.hero-section .container > *:nth-child(3) { animation-delay: 0.22s; }
.hero-section .container > *:nth-child(4) { animation-delay: 0.34s; }

div.script:
//
document.getElementById('newsletter-form').addEventListener('submit', function(e) {
  e.preventDefault();
  var email = document.getElementById('newsletter-email').value;
  var btn = document.getElementById('newsletter-btn');
  var form = document.getElementById('newsletter-form');
  var success = document.getElementById('newsletter-success');
  var error = document.getElementById('newsletter-error');
  btn.textContent = 'Submitting...';
  btn.disabled = true;
  var formData = new FormData();
  formData.append('entry.2134868049', email);
  fetch('https://docs.google.com/forms/d/e/1FAIpQLSeMVe-Sm4xa2L7ShMabxMveJZU5kFQrSH2QLymLlUrkFeRe6Q/formResponse', {
    method: 'POST',
    mode: 'no-cors',
    body: formData
  }).then(function() {
    form.style.display = 'none';
    success.style.display = 'block';
  }).catch(function() {
    btn.textContent = 'Subscribe Now';
    btn.disabled = false;
    error.style.display = 'block';
  });
});
//

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  var mobileBtn = document.getElementById('mobileMenuBtn');
  var closeBtn = document.getElementById('mobileCloseBtn');
  var overlay = document.getElementById('mobileOverlay');
  var headerRight = document.getElementById('headerRightCol');

  function toggleMenu() {
    if(headerRight.classList.contains('open')) {
      headerRight.classList.remove('open');
      overlay.classList.remove('active');
      document.body.style.overflow = '';
    } else {
      headerRight.classList.add('open');
      overlay.classList.add('active');
      document.body.style.overflow = 'hidden';
    }
  }

  if(mobileBtn && closeBtn && overlay && headerRight) {
    mobileBtn.addEventListener('click', toggleMenu);
    closeBtn.addEventListener('click', toggleMenu);
    overlay.addEventListener('click', toggleMenu);
  }
});
//
